output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "park_before_entering_single_file_aisle",
    "text": "A shopper must not push a cart from a cart bay into a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "cartBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "cartEntryIntoSingleFileAisle": {
          "pre": {
            "and": [
              "cartBay",
              "hasCart",
              "N"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartEntryIntoSingleFileAisle"
    }
  },
  {
    "id": "cartless_motion_only_in_narrow_excursion",
    "text": "After taking a cart, moving without it is only acceptable in the entrance area, a cart bay, or a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "entranceArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartlessAllowedArea": {
          "or": [
            "entranceArea",
            "cartBay",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessAllowedArea"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "Whenever a shopper parks or releases a cart, they are obliged to retrieve a cart again before the trip ends.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "cart_required_for_open_shelf_interaction",
    "text": "Interacting with a shelf without a cart is forbidden unless the shopper is in a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openShelfAccess": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShelfAccess",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_aisle_visits_must_be_purposeful",
    "text": "Entering a single-file shelf aisle obliges the shopper to interact with a shelf while in that aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileShelfAisle": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "singleFileShelfAisle"
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileShelfAisle",
      "discharge": {
        "and": [
          "INTERACT",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_wrong_way_cart_travel_in_wide_horizontal_aisles",
    "text": "With a cart, shoppers must not travel westward in wide horizontal aisles.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "wideHorizontalAisle",
          "W"
        ]
      }
    }
  },
  {
    "id": "exit_only_with_cart",
    "text": "A shopper is prohibited from exiting the store without a cart.",
    "abstraction": {
      "state_properties": {
        "exitCell": "at(11,7)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "exitCell",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
